<template>
  <div class="workspace-page batch-detail-page">
    <WorkspaceHeading :title="batch?.name || '批次详情'" :subtitle="batch ? `${batch.status} · ${activeMembers.length} 个当前成员` : '加载批次'">
      <el-button @click="back">返回批次</el-button><el-button v-if="batch && batch.status === '进行中'" type="warning" @click="requestReview">请求复盘</el-button><el-button v-if="batch && batch.status === '待复盘'" type="primary" @click="reviewVisible = true">开始复盘</el-button><el-button v-if="batch && batch.status !== '已归档'" @click="archive">归档</el-button>
    </WorkspaceHeading>
    <div v-if="error" class="page-error" role="alert">{{ error }}<el-button @click="load(true)">重试</el-button></div>
    <template v-if="batch">
      <section class="batch-overview-grid"><article><span>成员</span><strong>{{ activeMembers.length }}</strong></article><article><span>经营场景</span><strong>{{ Object.keys(batch.latest_review?.scenario_counts || scenarioCounts).length }}</strong></article><article><span>阶段</span><strong>{{ Object.keys(batch.latest_review?.stage_counts || stageCounts).length }}</strong></article><article><span>复盘</span><strong>{{ batch.review_changed ? '数据已变化' : batch.latest_review ? '已记录' : '未复盘' }}</strong></article></section>
      <section class="page-panel"><div class="panel-heading"><div><h2>批次信息</h2><p class="page-muted">记录这批网站的来源、目标与初始假设。</p></div><el-button type="primary" :loading="saving" :disabled="!dirty" @click="save">保存</el-button></div><div class="batch-form-grid"><el-form-item label="批次名称"><el-input v-model="form.name" maxlength="200" /></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option v-for="status in statuses" :key="status" :label="status" :value="status" /></el-select></el-form-item><el-form-item label="来源"><el-input v-model="form.source" maxlength="200" /></el-form-item><el-form-item label="目标"><el-input v-model="form.goal" type="textarea" :rows="2" maxlength="2000" /></el-form-item><el-form-item class="batch-form-full" label="初始假设"><el-input v-model="form.hypothesis" type="textarea" :rows="2" maxlength="2000" /></el-form-item><el-form-item class="batch-form-full" label="复盘结论"><el-input v-model="form.review_conclusion" type="textarea" :rows="2" maxlength="2000" /></el-form-item><el-form-item class="batch-form-full" label="下一步"><el-input v-model="form.next_action" maxlength="300" /></el-form-item></div></section>
      <section class="page-panel"><div class="panel-heading"><div><h2>批次成员</h2><p class="page-muted">可混合不同技术栈和经营场景；网站仍保留自己的阶段与场景。</p></div><div class="page-actions"><el-input v-model="search" clearable placeholder="搜索网站" aria-label="搜索批次成员" /><el-select v-model="scenarioFilter" clearable placeholder="经营场景" aria-label="按经营场景筛选"><el-option v-for="scenario in scenarios" :key="scenario" :label="scenario" :value="scenario" /></el-select><el-select v-model="stageFilter" clearable placeholder="阶段" aria-label="按阶段筛选"><el-option v-for="stage in stages" :key="stage" :label="stage" :value="stage" /></el-select></div></div><div v-if="selectedIds.size" class="portfolio-bulk-toolbar"><strong>已选 {{ selectedIds.size }} 个网站</strong><el-select v-model="bulkScenario" clearable filterable allow-create default-first-option placeholder="批量设置场景"><el-option v-for="scenario in scenarios" :key="scenario" :label="scenario" :value="scenario" /></el-select><el-button size="small" :loading="bulkSaving" @click="applyBulk({ operating_scenario: bulkScenario || null })">设置场景</el-button><el-select v-model="bulkStage" placeholder="批量设置阶段"><el-option v-for="stage in stages" :key="stage" :label="stage" :value="stage" /></el-select><el-button size="small" type="primary" :loading="bulkSaving" @click="applyBulk({ stage: bulkStage })">设置阶段</el-button><el-button size="small" text @click="selectedIds.clear()">清空</el-button></div><ul v-if="filteredMembers.length" class="batch-members-list"><li v-for="member in filteredMembers" :key="member.membership_id" :class="{ 'is-removed': member.membership_status === 'removed' }"><el-checkbox v-if="member.membership_status === 'active'" :model-value="selectedIds.has(member.website_id)" :aria-label="`选择网站：${member.name}`" @change="value => toggle(member.website_id, Boolean(value))" /><div class="batch-member-main"><button class="page-link" @click="openSite(member.website_id)">{{ member.name }}</button><small>{{ member.platform }} · {{ member.operating_scenario || '未设置场景' }} · {{ member.stage }}<template v-if="member.page_count != null"> · 页面 {{ member.page_count }}</template><template v-if="member.wp_article_count != null"> · 文章 {{ member.wp_article_count }}</template><template v-if="member.wp_calculator_count != null"> · 计算器 {{ member.wp_calculator_count }}</template></small><p v-if="member.member_note" class="page-muted">{{ member.member_note }}</p></div><span v-if="member.membership_status === 'removed'" class="page-muted">已移出</span><el-button v-else text type="danger" @click="remove(member.website_id)">移出</el-button></li></ul><p v-else class="page-empty">没有符合条件的成员。</p><div class="batch-add-members"><el-select v-model="addIds" multiple filterable collapse-tags placeholder="添加现有网站" aria-label="添加现有网站"><el-option v-for="site in availableSites" :key="site.id" :label="site.name" :value="site.id" /></el-select><el-input v-model="memberNote" placeholder="成员备注（可选）" aria-label="成员备注" /><el-button type="primary" :disabled="!addIds.length" :loading="memberSaving" @click="addMembers">加入批次</el-button></div></section>
      <section v-if="batch.latest_review" class="page-panel"><div class="panel-heading"><h2>最近复盘</h2><span class="page-muted">{{ batch.latest_review.reviewed_at }}</span></div><p v-if="batch.latest_review.conclusion">{{ batch.latest_review.conclusion }}</p><p v-if="batch.latest_review.next_action" class="page-muted">下一步：{{ batch.latest_review.next_action }}</p><div class="batch-review-summary"><span>成员 {{ batch.latest_review.member_count }}</span><span>页面 {{ batch.latest_review.content_totals.page_count }}</span><span>文章 {{ batch.latest_review.content_totals.wp_article_count }}</span><span>计算器 {{ batch.latest_review.content_totals.wp_calculator_count }}</span></div><p v-if="batch.review_changed" class="page-error">复盘后网站数据发生变化，建议重新复盘。</p></section>
    </template>
    <el-dialog v-model="reviewVisible" title="保存批次复盘" width="min(560px, 94vw)"><el-form label-position="top"><el-form-item label="复盘结论"><el-input v-model="reviewForm.conclusion" type="textarea" :rows="4" maxlength="2000" /></el-form-item><el-form-item label="下一步"><el-input v-model="reviewForm.next_action" maxlength="300" /></el-form-item></el-form><template #footer><el-button @click="reviewVisible=false">取消</el-button><el-button type="primary" :loading="reviewSaving" @click="completeReview">保存复盘</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import '../styles/workspace/batches.css'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import WorkspaceHeading from '../components/WorkspaceHeading.vue'
import { addBatchMembers, completeBatchReview, getBatch, removeBatchMembers, requestBatchReview, updateBatch, type BatchDetail } from '../api/batches'
import { bulkUpdateWebsites, getWebsites, type Website, type WebsiteStage } from '../api/websites'
const route = useRoute(); const router = useRouter(); const batch = ref<BatchDetail>(); const sites = ref<Website[]>([]); const loading = ref(false); const saving = ref(false); const memberSaving = ref(false); const bulkSaving = ref(false); const reviewSaving = ref(false); const error = ref(''); const search = ref(''); const scenarioFilter = ref(''); const stageFilter = ref(''); const addIds = ref<number[]>([]); const memberNote = ref(''); const selectedIds = reactive(new Set<number>()); const reviewVisible = ref(false)
const statuses = ['进行中', '待复盘', '已复盘', '已归档']; const stages: WebsiteStage[] = ['待评估', '验证', '增长', '维护', '暂停']; const scenarios = ['Astro 内容站', 'WordPress 计算器站', 'WordPress 资讯站', '通用网站']; const bulkScenario = ref(''); const bulkStage = ref<WebsiteStage>('待评估'); const reviewForm = reactive({ conclusion: '', next_action: '' }); const form = reactive({ name: '', source: '', goal: '', hypothesis: '', status: '进行中', review_conclusion: '', next_action: '' }); const baseline = ref('')
const activeMembers = computed(() => (batch.value?.members || []).filter(member => member.membership_status === 'active'))
const scenarioCounts = computed(() => activeMembers.value.reduce<Record<string, number>>((result, member) => { const key = member.operating_scenario || '未设置场景'; result[key] = (result[key] || 0) + 1; return result }, {}))
const stageCounts = computed(() => activeMembers.value.reduce<Record<string, number>>((result, member) => { result[member.stage] = (result[member.stage] || 0) + 1; return result }, {}))
const dirty = computed(() => baseline.value !== JSON.stringify(form))
const filteredMembers = computed(() => activeMembers.value.concat((batch.value?.members || []).filter(member => member.membership_status === 'removed')).filter(member => { const query = search.value.trim().toLowerCase(); return (!query || `${member.name} ${member.platform}`.toLowerCase().includes(query)) && (!scenarioFilter.value || member.operating_scenario === scenarioFilter.value) && (!stageFilter.value || member.stage === stageFilter.value) }))
const availableSites = computed(() => sites.value.filter(site => !activeMembers.value.some(member => member.website_id === site.id)))
const load = async (force = false) => { loading.value = true; error.value = ''; try { const id = Number(route.params.id); batch.value = await getBatch(id, force); sites.value = await getWebsites(force); Object.assign(form, { name: batch.value.name, source: batch.value.source || '', goal: batch.value.goal || '', hypothesis: batch.value.hypothesis || '', status: batch.value.status, review_conclusion: batch.value.review_conclusion || '', next_action: batch.value.next_action || '' }); baseline.value = JSON.stringify(form) } catch (e) { error.value = e instanceof Error ? e.message : '批次详情加载失败' } finally { loading.value = false } }
onMounted(() => { void load() }); watch(() => route.params.id, () => { void load(true) })
const back = () => router.push({ name: 'Batches' }); const openSite = (id: number) => router.push({ name: 'Home', query: { site: id } })
const save = async () => { if (!batch.value || !dirty.value) return; saving.value = true; try { await updateBatch(batch.value.id, form); await load(true); ElMessage.success('批次已保存') } catch (e) { ElMessage.error(e instanceof Error ? e.message : '批次保存失败') } finally { saving.value = false } }
const requestReview = async () => { if (!batch.value) return; try { await requestBatchReview(batch.value.id); await load(true); ElMessage.success('已请求复盘') } catch (e) { ElMessage.error(e instanceof Error ? e.message : '请求复盘失败') } }
const completeReview = async () => { if (!batch.value) return; reviewSaving.value = true; try { await completeBatchReview(batch.value.id, reviewForm); reviewVisible.value = false; await load(true); Object.assign(reviewForm, { conclusion: '', next_action: '' }); ElMessage.success('批次复盘已保存') } catch (e) { ElMessage.error(e instanceof Error ? e.message : '复盘保存失败') } finally { reviewSaving.value = false } }
const archive = async () => { if (!batch.value) return; try { await updateBatch(batch.value.id, { status: '已归档' }); await load(true); ElMessage.success('批次已归档') } catch (e) { ElMessage.error(e instanceof Error ? e.message : '批次归档失败') } }
const addMembers = async () => { if (!batch.value || !addIds.value.length) return; memberSaving.value = true; try { await addBatchMembers(batch.value.id, addIds.value, memberNote.value); addIds.value = []; memberNote.value = ''; await load(true) } catch (e) { ElMessage.error(e instanceof Error ? e.message : '加入批次失败') } finally { memberSaving.value = false } }
const remove = async (id: number) => { if (!batch.value) return; try { await removeBatchMembers(batch.value.id, [id], '从批次工作台移出'); await load(true) } catch (e) { ElMessage.error(e instanceof Error ? e.message : '移出批次失败') } }
const toggle = (id: number, value: boolean) => value ? selectedIds.add(id) : selectedIds.delete(id)
const applyBulk = async (fields: Record<string, unknown>) => { const ids = [...selectedIds]; if (!ids.length) return; bulkSaving.value = true; try { await bulkUpdateWebsites(ids, fields); selectedIds.clear(); await load(true) } catch (e) { ElMessage.error(e instanceof Error ? e.message : '批量更新失败') } finally { bulkSaving.value = false } }
</script>
